    // check every posible values
    for (int i = 0; i < m; i++) {
        for (int j = i + 1; j < m; j++) {
            for (int k = 0; k < n; k++) {
                for (int l = 0; l < n; l++) {
                    if (mat[i][k] + mat[j][l] == sum) {
                        result.push_back({mat[i][k],mat[j][l]});
                    }
                }
            }
        }
    }

    return result;
}

